// src/components/Hero.js
import React, { useState, useEffect } from 'react';
import './Hero.css';

const Hero = () => {
    const [slideIndex, setSlideIndex] = useState(0);
    const slides = [
        "assets/img1.jpg",
        "assets/img2.jpg",
        "assets/img3.jpg",
        "assets/img4.jpeg",
        "assets/img5.jpg"
    ];

    useEffect(() => {
        const interval = setInterval(() => {
            setSlideIndex((prev) => (prev + 1) % slides.length);
        }, 5000);
        return () => clearInterval(interval);
    }, [slides.length]);

    return (
        <>
            <section className="hero">
                <h1>Infinity Laghubitta Bittiya Sanstha Ltd.</h1>
                <p>Empowering Communities through Inclusive Financial Services across Nepal.</p>
            </section>

            <section className="slider-container">
                {slides.map((src, index) => (
                    <div 
                        key={index} 
                        className={`fade-slide ${index === slideIndex ? 'active' : ''}`}
                    >
                        <img src={src} alt={`Slider ${index + 1}`} />
                    </div>
                ))}
            </section>
        </>
    );
};

export default Hero;
